import importlib.util

spec = importlib.util.spec_from_file_location('aas_attack_submission', working_dir / 'attack.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)

bad_profiles = []
profile_checks = [(profile, 'gpt_oss') for profile in module.GPT_SEARCH_PROFILES]
profile_checks += [(profile, 'gemma') for profile in module.GEMMA_SEARCH_PROFILES]

for profile, route_hint in profile_checks:
    try:
        candidates = module._build_profile(profile, 3, route_hint=route_hint)
        if len(candidates) != 3 or any(len(c.user_messages) != 1 for c in candidates):
            bad_profiles.append((profile, route_hint, 'bad shape'))
    except Exception as exc:
        bad_profiles.append((profile, route_hint, repr(exc)))

assert not bad_profiles, bad_profiles[:5]

gpt_candidates = module.AttackAlgorithm({'route': 'gpt_oss', 'gpt_candidates': 3}).run(None, {'max_tool_hops': 8})
gemma_candidates = module.AttackAlgorithm({'route': 'gemma', 'gemma_candidates': 3}).run(None, {'max_tool_hops': 8})

assert len(gpt_candidates) == 3
assert len(gemma_candidates) == 3
assert all(len(c.user_messages) == 1 for c in gpt_candidates + gemma_candidates)
forbidden = 'SECRET' + '_MARKER'
assert all(forbidden not in c.user_messages[0] for c in gpt_candidates + gemma_candidates)
print('shape check OK; GPT profiles:', len(module.GPT_SEARCH_PROFILES), 'Gemma profiles:', len(module.GEMMA_SEARCH_PROFILES))


